/** Redis caching for cross-pod SSR module sharing */
import { rendererLogger } from "../../../../utils/index.js";
import { getSSRModuleRedisTTL, LOCAL_DEV_SSR_MODULE_TTL_SEC } from "../constants.js";
import { CacheBackends, createDistributedCodeCacheAccessor } from "../../../../cache/backend.js";
import { computeHash } from "../../../../utils/hash-utils.js";
import { getCacheBaseDir } from "../../../../utils/cache-dir.js";
import { isDevelopment } from "../../../../platform/environment.js";
const logger = rendererLogger.component("ssr-module-loader");
const SSR_MODULE_CACHE_PREFIX = "ssr-module";
// Mirrors the maximum key length accepted by veryfront-api.
const API_CACHE_KEY_MAX_LENGTH = 512;
const API_CACHE_KEY_PATTERN = /^[a-zA-Z0-9_:.\-/]+$/;
const SHA256_KEY_PREFIX = "sha256:";
/**
 * Lazy-loaded distributed cache gateway for cross-pod sharing.
 * Uses TokenizingCacheGateway to automatically handle tokenization/detokenization.
 */
const getDistributedCodeCache = createDistributedCodeCacheAccessor(() => CacheBackends.ssrModule(), "SSR-MODULE-LOADER", getCacheBaseDir);
/**
 * Background cache writes started by the render path.
 *
 * A transform publishes to the distributed cache without blocking the render on
 * it, which leaves the write running with nobody holding its promise. Tracking
 * those promises keeps the fire-and-forget deliberate rather than unobservable:
 * a caller that is about to tear down the cache directory -- a test, or a
 * shutdown path -- can wait for the disk to settle instead of racing it.
 *
 * Racing it is not harmless. The write fails mid-flight when its directory
 * disappears, and the failure lands in a cleanup path that is still running
 * after its owner has gone.
 */
const backgroundWrites = new Set();
/** Register a write started without an owner awaiting it. */
export function trackBackgroundWrite(write) {
    backgroundWrites.add(write);
    void write.catch(() => { }).finally(() => {
        backgroundWrites.delete(write);
    });
}
/**
 * Wait for every tracked background write to settle.
 *
 * Loops because a settling write can register another one; the set is empty
 * only when nothing is left in flight.
 */
export async function drainBackgroundWrites() {
    while (backgroundWrites.size > 0) {
        await Promise.allSettled([...backgroundWrites]);
    }
}
let distributedCacheEnabled = false;
/** Initialize distributed caching for SSR modules */
export async function initializeSSRDistributedCache() {
    distributedCacheEnabled = (await getDistributedCodeCache()) !== null;
    return distributedCacheEnabled;
}
/**
 * Report whether initialization actually resolved a distributed backend.
 * Stays false when the process runs on the in-memory backend, where
 * `initializeSSRDistributedCache` is never called.
 */
export function isSSRDistributedCacheEnabled() {
    return distributedCacheEnabled;
}
async function getDistributedCacheKey(cacheKey) {
    const fullyPrefixedKey = `${SSR_MODULE_CACHE_PREFIX}:${cacheKey}`;
    if (fullyPrefixedKey.length <= API_CACHE_KEY_MAX_LENGTH &&
        API_CACHE_KEY_PATTERN.test(fullyPrefixedKey)) {
        return cacheKey;
    }
    return `${SHA256_KEY_PREFIX}${await computeHash(fullyPrefixedKey)}`;
}
/**
 * Get code from distributed cache with automatic detokenization.
 * The TokenizingCacheGateway handles replacing __VF_CACHE_DIR__ tokens with local paths.
 */
export async function getFromRedis(cacheKey) {
    const gateway = await getDistributedCodeCache();
    if (!gateway)
        return null;
    try {
        // Use getCode() for automatic detokenization
        return await gateway.getCode(await getDistributedCacheKey(cacheKey));
    }
    catch (error) {
        logger.debug("Distributed cache get failed", { key: cacheKey, error });
        return null;
    }
}
/**
 * Store transformed code in distributed cache with automatic tokenization.
 * The TokenizingCacheGateway handles replacing absolute file:// paths with __VF_CACHE_DIR__ tokens.
 */
export async function setInRedis(cacheKey, code, options) {
    const gateway = await getDistributedCodeCache();
    if (!gateway)
        return;
    // The preview TTL is tuned for a shared branch cache and expires long before
    // a developer returns to the project, so an on-disk local dev cache would go
    // cold anyway. Keep those entries for a working day instead.
    const ttl = options?.ttlSeconds ??
        (isDevelopment() && gateway.type === "disk"
            ? LOCAL_DEV_SSR_MODULE_TTL_SEC
            : getSSRModuleRedisTTL(options?.isProduction ?? true));
    try {
        // Use setCode() for automatic tokenization
        await gateway.setCode(await getDistributedCacheKey(cacheKey), code, ttl);
    }
    catch (error) {
        logger.debug("Distributed cache set failed", { key: cacheKey, error });
    }
}
